            scrollContainerRef={scrollRef}
            containerClassName={styles.floatContainer}
            textClassName={styles.floatText}
            animationDuration={1}
            ease="back.inOut(2)"
            scrollStart="top bottom"
            scrollEnd="center center"
            stagger={0.03}
          >QUIET FLOW</Component> : null}
        </section>
      </div></>}

